/** A binary (xlsx) response body as a Buffer. */
const binary = (r: request.Response, cb: (err: Error | null, body: Buffer) => void) => {
  const chunks: Buffer[] = []
  r.on('data', (c: Buffer) => chunks.push(c))
  r.on('end', () => cb(null, Buffer.concat(chunks)))
}
/** The first sheet of an xlsx body (or none). */
async function sheet(body: unknown) {
  const wb = new ExcelJS.Workbook()
  await wb.xlsx.load(body as Parameters<typeof wb.xlsx.load>[0])
  return wb.worksheets[0]
}
const cells = (ws: ExcelJS.Worksheet, row: number, length: number) =>
  Array.from({ length }, (_, i) => ws.getRow(row).getCell(i + 1).value ?? null)

describe('export', () => {
  /** GET /export as the parsed first sheet, with the response. */
  async function exported(who: keyof typeof tokens, query: object, headers: object = {}) {
    const res = await call(who, 'get', '/export')
      .query(query)
      .set(headers as Record<string, string>)
      .buffer(true)
      .parse(binary)
    return { res, ws: res.status === 200 ? await sheet(res.body) : undefined }
  }
  const row = (ws: ExcelJS.Worksheet, n: number) => cells(ws, n, HEADERS.length)

  it('export: every row (no paging) in list order as .xlsx, headers translated, times in the zone', async () => {
    const tag = unique()
    await add(body(`${tag}-a`))
    const { id } = await add(body(`${tag}-b`, { userType: 'member' }))
    // this test's rows only (the export honours the list filters): every action-log write lands in this
    // table without being awaited, the export's own one too, while its later 1000-row batches are read
    // (offset paging, newest first: a table of the full suite's size then exports one row twice)
    const { res, ws } = await exported('admin', { sort: '-id', pageSize: 1, domain: `${tag}-` })
    expect(res.status).toBe(200)
    expect(res.headers['content-type']).toContain('spreadsheetml.sheet')
    expect(res.headers['content-disposition']).toBe('attachment; filename="actionLogs.xlsx"')
    expect(row(ws!, 1)).toEqual(HEADERS.map((k) => t('zh-CN', k)))
    // the header and both rows (no paging), newest first
    expect(ws!.actualRowCount).toBe(3)
    expect(row(ws!, 2)[0]).toBe(`${tag}-b`)
    expect(row(ws!, 3)[0]).toBe(`${tag}-a`)
    expect(row(ws!, 2)[4]).toBe('会员')
    expect(row(ws!, 3)[4]).toBe('管理员')
    // created_at (UTC) in core.default_timezone (Asia/Shanghai, +8h) unless X-Timezone says otherwise
    const [{ at }] = await ds.query('SELECT created_at AS at FROM aud_action_log WHERE id = ?', [
      id,
    ])
    const local = (d: Date, hours: number) =>
      new Date(d.getTime() + hours * 3600_000).toISOString().slice(0, 19).replace('T', ' ')
    expect(row(ws!, 2)[9]).toBe(local(at, 8))
    // this spec's rows only: the first export's own log row is newer (and may be a second later)
    const utc = await exported('admin', { sort: '-id', domain: tag }, { 'X-Timezone': 'UTC' })
    expect(row(utc.ws!, 2)[9]).toBe(local(at, 0))
  })

  it('export: English headers and dict labels, with future identity codes unchanged', async () => {
    const tag = unique()
    await add(body(`${tag}-a`))
    await add(body(`${tag}-b`, { userType: 'member' }))
    await add(body(`${tag}-c`, { userType: 'future-kind' }))
    const { ws } = await exported(
      'admin',
      { sort: '-id', domain: `${tag}-` },
      { 'Accept-Language': 'en-US' },
    )
    expect(row(ws!, 1)).toEqual(HEADERS.map((k) => t('en-US', k)))
    expect(row(ws!, 2)[4]).toBe('future-kind')
    expect(row(ws!, 3)[4]).toBe('Member')
    expect(row(ws!, 4)[4]).toBe('Administrator')
  })

  it('export: 403 without audit.actionLog.export, 400 for a bad query, action-logged', async () => {
    expect((await exported('reader', {})).res.status).toBe(403)
    expect((await exported('admin', { sort: 'traceId' })).res.status).toBe(400)
    const traceId = `${PREFIX}${process.pid}-export`
    await exported('admin', { domain: unique() }, { 'X-Request-Id': traceId })
    expect(await logOf(ds, traceId)).toMatchObject({
      domain: 'audit.actionLog',
      verb: 'export',
      ok: 1,
    })
  })
})

